(async()=>{const f=document.querySelector("iframe"),w=f.contentWindow,d=f.contentDocument;const wait=()=>new Promise(r=>setTimeout(r,180));const results=[];for(const width of [320,390,768,1024,1440]){f.style.width=width+"px";await wait();for(let i=0;i<8;i++){const nav=d.querySelectorAll(".nav-item")[i];nav.click();await wait();const body=d.body;const controls=[...d.querySelectorAll("button,input,select,textarea")].filter(e=>e.getClientRects().length&&!e.disabled);const unlabeled=controls.filter(e=>!(e.getAttribute("aria-label")||e.getAttribute("aria-labelledby")||e.labels?.length||e.textContent.trim()||e.title)).map(e=>e.outerHTML.slice(0,120));const tiny=controls.filter(e=>{const r=e.getBoundingClientRect();return r.width<24||r.height<24}).map(e=>(e.getAttribute("aria-label")||e.textContent.trim()||e.tagName).slice(0,35));results.push({width,page:nav.textContent.trim(),client:d.documentElement.clientWidth,scroll:d.documentElement.scrollWidth,unlabeled,tiny:tiny.slice(0,6),tinyCount:tiny.length})}}return results})()
